{
  "name": "SRS830 锁相放大器",
  "name_en": "SRS830 Lock-In Amplifier",
  "manufacturer": "Stanford Research Systems",
  "description": "Stanford Research Systems 的 SRS830 锁相放大器，用于相敏检测与弱信号测量。该设备可设置参考频率、相位、输入耦合和采样参数，并支持 X、Y、R、θ 等量的缓冲采集、快照读取与自动调零/调相。",
  "description_en": "The SRS830 from Stanford Research Systems is a lock-in amplifier for phase-sensitive detection and weak-signal measurements. It supports control of reference frequency, phase, input coupling, and sampling parameters, and provides buffered acquisition, snapshot readout, and auto offset/auto phase functions for quantities such as X, Y, R, and theta.",
  "actions": [
    {
      "action_name": "auto-amplitude",
      "description": "获取/设置参考输出幅度。",
      "description_en": "Get/set the reference output amplitude."
    },
    {
      "action_name": "auto-auto_offset",
      "description": "对选定测量模式自动调零偏置。",
      "description_en": "Automatically zero the offset for the selected measurement mode."
    },
    {
      "action_name": "auto-auto_phase",
      "description": "自动调整锁相相位。",
      "description_en": "Automatically adjust the lock-in phase."
    },
    {
      "action_name": "auto-buffer_mode",
      "description": "获取/设置数据缓冲模式。",
      "description_en": "Get/set the data buffer mode."
    },
    {
      "action_name": "auto-clear_data_buffer",
      "description": "清空内部数据缓冲区。",
      "description_en": "Clear the internal data buffer."
    },
    {
      "action_name": "auto-coupling",
      "description": "获取/设置输入耦合方式。",
      "description_en": "Get/set the input coupling mode."
    },
    {
      "action_name": "auto-data_snap",
      "description": "同时抓取两个选定参数的瞬时值。",
      "description_en": "Capture an instantaneous snapshot of two selected parameters."
    },
    {
      "action_name": "auto-data_transfer",
      "description": "获取/设置数据传输模式。",
      "description_en": "Get/set the data transfer mode."
    },
    {
      "action_name": "auto-frequency",
      "description": "获取/设置参考频率。",
      "description_en": "Get/set the reference frequency."
    },
    {
      "action_name": "auto-frequency_source",
      "description": "获取/设置参考频率源。",
      "description_en": "Get/set the reference frequency source."
    },
    {
      "action_name": "auto-init",
      "description": "初始化测量参数，包括采样率和缓冲模式。",
      "description_en": "Initialize measurement settings, including sample rate and buffer mode."
    },
    {
      "action_name": "auto-input_shield_ground",
      "description": "获取/设置输入屏蔽接地方式。",
      "description_en": "Get/set the input shield grounding mode."
    },
    {
      "action_name": "auto-pause",
      "description": "暂停数据采集。",
      "description_en": "Pause data acquisition."
    },
    {
      "action_name": "auto-phase",
      "description": "获取/设置参考相位。",
      "description_en": "Get/set the reference phase."
    },
    {
      "action_name": "auto-read_data_buffer",
      "description": "读取指定通道的整个数据缓冲区。",
      "description_en": "Read the entire data buffer for the specified channel."
    },
    {
      "action_name": "auto-sample_rate",
      "description": "获取/设置数据采样率。",
      "description_en": "Get/set the data sampling rate."
    },
    {
      "action_name": "auto-set_channel_display",
      "description": "设置通道显示量及比值显示方式。",
      "description_en": "Set the displayed quantity and ratio mode for a channel."
    },
    {
      "action_name": "auto-set_offset_expand",
      "description": "设置通道偏置和扩展倍数。",
      "description_en": "Set the channel offset and expand factor."
    },
    {
      "action_name": "auto-start_data_transfer",
      "description": "启动缓冲数据传输。",
      "description_en": "Start buffered data transfer."
    },
    {
      "action_name": "auto-start_scan",
      "description": "开始扫描/采集过程。",
      "description_en": "Start the scan or acquisition process."
    },
    {
      "action_name": "auto-take_measurement",
      "description": "按指定采样率和样本数执行一次缓冲测量。",
      "description_en": "Perform a buffered measurement with the specified sample rate and number of samples."
    },
    {
      "action_name": "auto-num_data_points",
      "description": "获取缓冲区中的数据点数量。",
      "description_en": "Get the number of data points in the buffer."
    }
  ],
  "tag_hints": [
    "lock-in amplifier",
    "phase-sensitive detection",
    "weak signal measurement",
    "reference frequency control",
    "buffered acquisition",
    "X Y R theta readout",
    "SCPI instrument"
  ]
}

